	"gift_premium_terms_footer": "‏يتم احتساب سعر الاشتراك الهدية عند الشراء وهو غير قابل للاسترداد. إنه استخدام لمرة واحدة، وهو غير قابل للاستبدال، وغير قابل للدمج، وليس له قيمة نقدية. يبدأ الاشتراك بعد قيام منصة X بالمراجعة والتعيين للمستلم، الذي يجب أن يقر بـ %1$s والسياسات المتبعة لدينا. إذا فشل المستلِم في تلبية أي متطلبات للأهلية أو ألغى الاشتراك أو رفض شروطنا وسياساتنا، فإن الهدية تكون غير قابلة للحصول عليها وغير قابلة للاسترداد. قد يتم تطبيق الضرائب. قد تتغير الشروط. %2$s.",
