	"golive__tip_broadcaster_1": "‏<b>نصيحة:</b> نشكرك على البث المباشر! رحب بالأشخاص عن طريق قول \\\"مرحبًا\\\" لهم عندما ينضمون إلى الفيديو الخاص بك.",
	"golive__tip_broadcaster_10": "‏<b>تلميح:</b> شكرًا لك على البث المباشر على X! <3",
	"golive__tip_broadcaster_2": "‏<b>نصيحة:</b> حاول أن تذكر الأشخاص بأسمائهم عندما ينضمون إلى البث المباشر للفيديو، سوف يشعرهم ذلك بالإثارة!",
	"golive__tip_broadcaster_3": "‏<b>نصيحة:</b> تأكد من البث المباشر لعدة دقائق على الأقل لكي يصبح من السهل على الأشخاص أن يعثروا عليك.",
	"golive__tip_broadcaster_4": "‏<b>نصيحة:</b> اسأل مشاهديك عن بلدهم، فهذه طريقة رائعة لإذابة الجليد بينك وبينهم.",
	"golive__tip_broadcaster_5": "‏<b>نصيحة:</b> اشكر الأشخاص على مشاركتهم ورد على تعليقاتهم لكي يستمروا في المشاهدة.",
	"golive__tip_broadcaster_6": "‏<b>نصيحة:</b> إذا فقدت الاتصال أثناء البث المباشر، انتقل إلى مكان به إشارة أفضل.",
	"golive__tip_broadcaster_7": "‏<b>نصيحة:</b> اطلب من الأشخاص أن يتابعوك حتى يمكن تنبيهم في المرة القادمة التي تبدأ فيها البث المباشر.",
	"golive__tip_broadcaster_8": "‏<b>نصيحة:</b> ابدأ الفيديو المباشر بالتحية مباشرة. فالأشخاص الذين سيشاهدونه بعد ذلك سيحبون ذلك.",
	"golive__tip_broadcaster_9": "‏<b>نصيحة:</b> اشكر الأشخاص على مشاهدتم قبل أن تنهي الفيديو المباشر.",
	"golive__tip_pre_broadcast_1": "‏<b>نصيحة:</b> اكتب عنوانًا قبل بدأ البث المباشر لمساعدة الأشخاص على اكتشاف الفيديو الخاص بك.",
	"golive__tip_pre_broadcast_2": "‏<b>نصيحة:</b> يساعد العنوان الوصفي الأشخاص في فهم موضوع الفيديو المباشر.",
	"golive__tip_pre_broadcast_3": "‏<b>نصيحة:</b> هل تحتاج إلى أفكار؟ يمكنك تقديم نزهة، أو مشاركة موهبة أو التحدث حول شيء يهمك.",
	"golive__tip_pre_broadcast_4": "‏<b>نصيحة:</b> تأكد من وجود إشارة هاتف قوية قبل البث المباشر.",
	"golive__tip_pre_broadcast_5": "‏<b>نصيحة:</b> أضف وسمًا إلى العنوان لمساعدة الأشخاص في اكتشاف الفيديو المباشر الخاص بك.",
	"golive__tip_pre_broadcast_6": "‏<b>تلميح:</b> هذه هي كل التلميحات التي لدينا حاليًا، شكرًا لك على البث المباشر على X!",
