	"payment_international_wire_disclaimer_dispute_with_url_format": "‏يحق لك الاعتراض على أي خطأ في معاملتك. إذا كنت تعتقد بوجود خطأ، يُرجى التواصل مع شركة X Payments LLC خلال {days} يوم عبر الاتصال على الرقم {phone}، أو عبر البريد على العنوان {address}، أو بزيارة الموقع الإلكتروني {url}. كما يمكنك التواصل معنا للحصول على شرح كتابي لحقوقك.",
