	"profile_smart_blocked_autoblocked_by_twitter_description": "\"‏تم حظرك تلقائيًا من مشاهدة منشورات ‎@%1$s والتفاعل معها بشكلٍ مؤقت. تم هذا الحظر أثناء تشغيل وضع الأمان وقد وضعنا علامة تُفيد بأن تفاعلاتكِ قد تكون مسيئة أو مزعجة.\n\nنعلم أن عمليات الحظر التلقائي لا تحدث بشكلٍ صحيح طوال الوقت، لذلك نحن نعمل على تحسين اكتشافنا لذلك.\n\n{{}}ما المقصود %2$sبوضع %2$sالأمان؟{{}}\n\nفيما يلي بعض الطرق للحفاظ على جودة محادثاتك وتجنب حظرها تلقائيًا.\"",
