	"ps__tip_broadcaster_8": "‏<b>نصيحة:</b> ابدأ بثك بإلقاء التحية مباشرة. سوف يعجب بذلك مشاهدو ردك.",
	"ps__tip_broadcaster_9": "‏<b>نصيحة:</b> اشكر مشاهديك على المشاهدة قبل أن تنهي البث.",
	"ps__tip_pre_broadcast_1": "‏<b>نصيحة:</b> اكتب عنوانًا قبل أن تبدأ بثك وقابل الأشخاص الذين لديهم اهتمامات مشابهة!",
	"ps__tip_pre_broadcast_2": "‏<b>نصيحة:</b> يساعد العنوان الوصفي الأشخاص في فهم موضوع البث الخاص بك.",
	"ps__tip_pre_broadcast_3": "‏<b>نصيحة:</b> هل تحتاج إلى أفكار؟ يمكنك بث جولة أو مشاركة موهبة أو التحدث حول موضوع يهمك.",
	"ps__tip_pre_broadcast_4": "‏<b>نصيحة:</b> تأكد من توفر إشارة هاتف قوية لديك قبل البث المباشر.",
	"ps__tip_pre_broadcast_5": "‏<b>نصيحة:</b> شارك عمليات البث الخاصة بك على X للوصول إلى عدد أكبر من المشاهدين.",
	"ps__tip_pre_broadcast_6": "‏<b>نصيحة:</b> إذا كنت تتابع أشخاصًا يتابعونك أيضًا، يمكنك البث بشكل خاص لهم.",
	"ps__tip_pre_broadcast_8": "‏<b>نصيحة:</b> أضف وسمًا ذا صلة إلى العنوان الخاص بك لمساعدة الأشخاص في اكتشاف بثك.",
	"ps__tip_pre_broadcast_9": "‏<b>نصيحة:</b> هذه هي كل النصائح التي لدينا حاليًا، شكرًا على استخدام Periscope!",
	"ps__tip_viewer_1": "‏<b>نصيحة:</b> أنت أحد الأوائل الذين انضموا، اكتب تعليقًا واكتب فيه عبارات الترحيب!",
	"ps__tip_viewer_2": "‏<b>نصيحة:</b> اكتب تعليقًا وأعلم <b>%1$s</b> بأنك هنا!",
	"ps__tip_viewer_3": "‏<b>نصيحة:</b> أعلم<b>%1$s</b> بمكان مشاهدتك!",
	"ps__tip_viewer_4": "‏<b> نصيحة:</b>قم بالترحيب للدردشة مع <b>%1$s</b> والمشاهدين الآخرين.",
