	"room_settings_clips_description": "\"‏عند إنشاء كليب، سيتم التقاط آخر 30 ثانية من الصوت. \n \nبصفتك مضيفًا، يمكنك حذف الكليبات التي أنشأها أشخاصٌ آخرون من مساحتك. ولكن إذا حذفت مقطعًا واحدًا من مساحتك، فسيتم حذف جميع المقاطع من المساحة نفسها. \n \nإذا سجلت مساحة ثم حذفتها، فسيتم أيضًا حذف أي كليب من تلك المساحة. \n \nتنتهي صلاحية جميع الكليبات بعد 30 يومًا.\"",
