	"tipjar_disclaimer_dialog_description": "‏يخضع إرسال الإكراميات لشروط منصة الجهة الخارجية، بما في ذلك المعلومات التي تتم مشاركتها عن الأشخاص الذين يرسلون الأموال فيما بينهم. لا يتم إرسال أي أموال إلى X.",
